{
  "technical_and_design_decisions": [
    "Implement the Capabilities Framework using protobuf-based configuration maps at channel, application, and orderer levels.",
    "Enforce crash-on-unsupported-capabilities behavior for simplicity and data integrity in v1.1.",
    "Use dependency injection to remove chaincode singletons, replacing global state with injectable components.",
    "Refactor MSPConfig into an interface to decouple configuration generation from configtxgen.",
    "Integrate CouchDB performance metrics with existing Prometheus/OpenMetrics monitoring infrastructure.",
    "Implement RYW support via a new chaincode shim API method (GetTrxState) with state database transaction visibility.",
    "Generate core.yaml and orderer.yaml from a unified World config using a dedicated configuration builder tool.",
    "Design the validation interface for the new lifecycle to include a special case for '+lifecycle' with auto-generated endorsement policies."
  ],
  "assumptions": [
    "The development team has prior experience with Hyperledger Fabric's codebase and architecture.",
    "Existing testing frameworks (Go unit tests, integration tests) are sufficient for validating new features.",
    "Documentation and video creation for U3 will be handled by the same development team.",
    "The World config for U7 is a predefined YAML/JSON structure with all required configuration parameters.",
    "CouchDB performance metrics will be collected via existing peer metrics endpoints without requiring new infrastructure.",
    "The '+lifecycle' chaincode validation policy will be hardcoded as a majority endorsement policy for v1.1.",
    "All non-backwards compatible changes for U1 will be encapsulated under the 'V1.1' capability flag.",
    "The crash-on-unsupported-capabilities behavior will be implemented as a panic with a clear error message."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Design Capabilities Framework Structure",
      "activity_description": "Define protobuf structures and channel config schema for channel, application, and orderer capability maps.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement Orderer Capability Checks",
      "activity_description": "Add capability validation logic in the orderer to enforce required capabilities and crash on mismatch.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement Peer Capability Checks",
      "activity_description": "Add capability validation logic in the peer to enforce required capabilities and crash on mismatch.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "A4",
      "activity_name": "Handle Crash on Unsupported Capabilities",
      "activity_description": "Implement panic/crash behavior with clear error messages when binaries lack required capabilities.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A5",
      "activity_name": "Update Upgrade Process for Capabilities",
      "activity_description": "Modify reconfiguration transaction handling to set V1.1 capabilities in all three maps during upgrades.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "A6",
      "activity_name": "Test Capabilities Framework",
      "activity_description": "Write unit and integration tests for capability validation, crash behavior, and upgrade scenarios.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A7",
      "activity_name": "Add RYW API to Chaincode Shim",
      "activity_description": "Implement GetTrxState method in the chaincode shim to allow access to in-transaction writes.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "A8",
      "activity_name": "Update State Database for RYW",
      "activity_description": "Modify peer state database handling to expose in-transaction writes to chaincode via GetTrxState.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A9",
      "activity_name": "Test RYW Functionality",
      "activity_description": "Write tests to verify chaincode can read keys written in the same transaction.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A10",
      "activity_name": "Create Documentation and Video for Org Addition",
      "activity_description": "Produce a PPT overview and step-by-step video demonstrating adding organizations to a running network.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A11",
      "activity_name": "Write Org Addition Documentation",
      "activity_description": "Document the process for adding organizations without network downtime.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A12",
      "activity_name": "Add CouchDB Performance Metrics",
      "activity_description": "Instrument CouchDB query operations to collect latency and throughput metrics.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "A13",
      "activity_name": "Integrate Metrics with Monitoring",
      "activity_description": "Expose CouchDB metrics via existing peer metrics endpoints for Prometheus/OpenMetrics.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A14",
      "activity_name": "Test CouchDB Metrics",
      "activity_description": "Verify metrics collection and integration with monitoring tools.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A15",
      "activity_name": "Refactor MSPConfig to Interface",
      "activity_description": "Convert MSPConfig into an interface to allow custom configuration generation outside configtxgen.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A16",
      "activity_name": "Update Configtxgen and Tools",
      "activity_description": "Modify configtxgen and related tools to work with the new MSPConfig interface.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "A17",
      "activity_name": "Test MSPConfig Interface",
      "activity_description": "Validate that custom configurations can be generated using the new interface.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A18",
      "activity_name": "Remove Chaincode Singletons",
      "activity_description": "Identify and refactor all chaincode singletons to use dependency injection.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A19",
      "activity_name": "Update Tests for Singleton Removal",
      "activity_description": "Modify existing tests to work with the refactored dependency-injected chaincode components.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A20",
      "activity_name": "Implement Config Generation from World Config",
      "activity_description": "Create a tool to generate core.yaml and orderer.yaml from a unified World config.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "A21",
      "activity_name": "Test Config Generation",
      "activity_description": "Verify generated configuration files match expected formats and values.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A22",
      "activity_name": "Implement Validation Interface for Lifecycle",
      "activity_description": "Create an interface to return validation parameters for chaincodes, including the '+lifecycle' special case.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A23",
      "activity_name": "Handle '+lifecycle' Validation Policy",
      "activity_description": "Implement auto-generated majority endorsement policy for the '+lifecycle' chaincode.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A24",
      "activity_name": "Test Validation Interface",
      "activity_description": "Validate the interface returns correct parameters for regular and '+lifecycle' chaincodes.",
      "most_likely_effort": 10
    }
  ],
  "reported_total": {
    "most_likely_effort": 325
  }
}

